using MahjongNight.Core;
using UnityEngine;

namespace MahjongNight.Game
{
    /// <summary>
    /// The traditional tile-face artwork: Resources/TileFaces.png, generated by
    /// Tools/generate_tile_faces.py (8 columns × 6 rows of 256×340 cells in a 2048² image,
    /// kind index k at column k % 8, row k / 8 from the top-left).
    /// </summary>
    public static class TileAtlas
    {
        private const int Columns = 8;
        private const float CellWidth = 256f / 2048f;
        private const float CellHeight = 340f / 2048f;

        private static Texture2D texture;
        private static bool loaded;

        /// <summary>The atlas, or null if it's missing (tiles then fall back to text labels).</summary>
        public static Texture2D Texture
        {
            get
            {
                if (!loaded)
                {
                    texture = Resources.Load<Texture2D>("TileFaces");
                    loaded = true;
                    if (texture == null)
                        Debug.LogWarning("TileFaces atlas not found in Resources; using text labels.");
                }
                return texture;
            }
        }

        /// <summary>UV rectangle (origin bottom-left, as Unity expects) of a tile's face.</summary>
        public static Rect UvRect(Tile tile)
        {
            int k = tile.KindIndex;
            int col = k % Columns;
            int row = k / Columns;
            return new Rect(col * CellWidth, 1f - (row + 1) * CellHeight, CellWidth, CellHeight);
        }
    }
}
